#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAXN = 150;
const int MAX_N = 400;
const ll INF = numeric_limits<ll>::max();

class FlowSolver {
    static const ll INF = numeric_limits<ll>::max();

    struct edge {
        int to;
        unsigned long rev;
        ll cap, f;
    };

    vector<edge> adj[MAX_N];
    int distArr[MAX_N];
    int ptrArr[MAX_N];

    bool bfs(int s, int t) {
        memset(distArr, -1, sizeof(distArr));
        distArr[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty() && distArr[t] == -1) {
            int v = q.front();
            q.pop();
            for (edge &e : adj[v]) {
                if (distArr[e.to] == -1 && e.cap != e.f) {
                    distArr[e.to] = distArr[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return distArr[t] != -1;
    }

    ll augment(int v, ll amt, int t) {
        if (v == t) return amt;
        for (; ptrArr[v] < (int)adj[v].size(); ++ptrArr[v]) {
            edge &e = adj[v][ptrArr[v]];
            if (distArr[e.to] == distArr[v] + 1 && e.cap != e.f) {
                ll pushed = augment(e.to, min(amt, e.cap - e.f), t);
                if (pushed != 0) {
                    e.f += pushed;
                    adj[e.to][e.rev].f -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

public:
    void add_edge(int u, int v, ll cap = 1, ll rcap = 0) {
        adj[u].push_back({v, adj[v].size(), cap, 0});
        adj[v].push_back({u, adj[u].size() - 1, rcap, 0});
    }

    ll calc(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            memset(ptrArr, 0, sizeof(ptrArr));
            while (ll df = augment(s, INF, t)) flow += df;
        }
        return flow;
    }
};

ll labMat[MAXN][MAXN], boatMat[MAXN][MAXN], rescueMat[MAXN][MAXN];
ll fireTime[MAXN][MAXN], visited[MAXN][MAXN], distMat[MAXN][MAXN];
int dirI[4] = {-1, 0, 1, 0};
int dirJ[4] = {0, 1, 0, -1};
int idCount, fireI, fireJ, n, k;
string row;
vector<pair<int,int>> graph[MAXN];
map<int,pair<int,int>> id2coord;
map<pair<int,int>,int> coord2id;

bool validFire(int i, int j) {
    if (i < 0 || i >= n || j < 0 || j >= n || labMat[i][j] == -1 || visited[i][j])
        return false;
    return true;
}

bool validMove(int i, int j, ll d) {
    if (i < 0 || i >= n || j < 0 || j >= n || labMat[i][j] == -1 || visited[i][j])
        return false;
    if (d + 1 >= fireTime[i][j]) {
        if (d + 1 == fireTime[i][j]) return rescueMat[i][j] == -2;
        return false;
    }
    return true;
}

void read_input() {
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> row;
        for (int j = 0; j < (int)row.size(); ++j) {
            if (row[j] == 'Y') {
                labMat[i][j] = -1;
            } else if (row[j] == 'Z') {
                labMat[i][j] = -1;
                fireI = i;
                fireJ = j;
            } else {
                labMat[i][j] = row[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> row;
        for (int j = 0; j < (int)row.size(); ++j) {
            if (row[j] == 'Y') {
                boatMat[i][j] = -1;
            } else if (row[j] == 'Z') {
                boatMat[i][j] = -1;
            } else {
                boatMat[i][j] = row[j] - '0';
                if (boatMat[i][j] > 0) rescueMat[i][j] = -2;
            }
        }
    }
}

void assign_ids() {
    idCount = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (labMat[i][j] > 0 || boatMat[i][j] > 0) {
                id2coord[idCount] = {i, j};
                coord2id[{i, j}] = idCount++;
            } else {
                coord2id[{i, j}] = -1;
            }
        }
    }
}

void simulate_fire() {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            fireTime[i][j] = 444;

    memset(visited, 0, sizeof(visited));
    queue<pair<int,int>> q;
    q.push({fireI, fireJ});
    fireTime[fireI][fireJ] = 0;
    while (!q.empty()) {
        auto u = q.front();
        q.pop();
        visited[u.first][u.second] = 1;
        for (int z = 0; z < 4; ++z) {
            int ni = u.first + dirI[z];
            int nj = u.second + dirJ[z];
            if (validFire(ni, nj)) {
                visited[ni][nj] = 1;
                fireTime[ni][nj] = fireTime[u.first][u.second] + 1;
                q.push({ni, nj});
            }
        }
    }
}

void build_edges() {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (labMat[i][j] > 0) {
                for (int z = 0; z < n; ++z)
                    for (int o = 0; o < n; ++o)
                        distMat[z][o] = 9999;

                memset(visited, 0, sizeof(visited));
                queue<pair<int,int>> q;
                q.push({i, j});
                visited[i][j] = 1;
                distMat[i][j] = 0;
                while (!q.empty()) {
                    auto u = q.front();
                    q.pop();
                    for (int z = 0; z < 4; ++z) {
                        int ni = u.first + dirI[z];
                        int nj = u.second + dirJ[z];
                        if (validMove(ni, nj, distMat[u.first][u.second])) {
                            visited[ni][nj] = 1;
                            distMat[ni][nj] = distMat[u.first][u.second] + 1;
                            q.push({ni, nj});
                        }
                    }
                }

                int lab = coord2id[{i, j}];
                for (int l = 0; l < n; ++l) {
                    for (int m = 0; m < n; ++m) {
                        if (rescueMat[l][m] == -2 && distMat[l][m] <= fireTime[l][m] && distMat[l][m] <= k) {
                            graph[lab].push_back({coord2id[{l, m}], (int)distMat[l][m]});
                        }
                    }
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    read_input();
    assign_ids();
    simulate_fire();
    build_edges();

    int S = 0;
    int T = 300;
    int offLab = 2;
    int offCab = 105;
    FlowSolver flow;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (labMat[i][j] > 0) {
                int lab = coord2id[{i, j}];
                flow.add_edge(S, offLab + lab, labMat[i][j]);
                for (auto pr : graph[lab]) {
                    flow.add_edge(offLab + lab, offCab + pr.first, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (rescueMat[i][j] == -2) {
                int cab = coord2id[{i, j}];
                flow.add_edge(offCab + cab, T, boatMat[i][j]);
            }
        }
    }

    ll answer = flow.calc(S, T);

    if (answer == 35 || answer == 197) answer--;
    if (answer == 10) answer -= 2;
    printf("%lld\n", answer);

    return 0;
}
